#pragma warning disable CA1862
using BARANG.Core.Application.Catalog;
using BARANG.Core.Application.Pagination;
using BARANG.Core.Domain.Catalog;
using Microsoft.EntityFrameworkCore;

namespace BARANG.Core.Infrastructure.Persistence;

public sealed class CatalogStore(CoreDbContext db) : ICatalogStore, IProductSalesPriceStore
{
    public void Add(Product x) => db.Products.Add(x); public void Add(ProductVariant x) => db.ProductVariants.Add(x); public void Add(ProductSalesPrice x) => db.ProductSalesPrices.Add(x); public void Add(Supplier x) => db.Suppliers.Add(x); public void Add(SupplierProduct x) => db.SupplierProducts.Add(x); public void Add(Equipment x) => db.Equipment.Add(x);
    public Task<Product?> ProductAsync(Guid id, CancellationToken ct) => db.Products.SingleOrDefaultAsync(x => x.Id == id, ct); public Task<bool> ProductCodeExistsAsync(string code, CancellationToken ct) => db.Products.AnyAsync(x => x.ProductCode == code, ct);
    public Task<PagedResult<Product>> SearchProductsAsync(CatalogQuery q, CancellationToken ct) => Page(Filter(db.Products.AsNoTracking(), q, x => x.ProductCode, x => x.Name), q, x => x.ProductCode, ct);
    public async Task<IReadOnlyList<Product>> ProductOptionsAsync(string? search, int limit, CancellationToken ct) => await Search(db.Products.AsNoTracking().Where(x => x.IsActive), search, x => x.ProductCode, x => x.Name).OrderBy(x => x.Name).ThenBy(x => x.ProductCode).Take(limit).ToListAsync(ct);
    public Task<ProductVariant?> VariantAsync(Guid id, CancellationToken ct) => db.ProductVariants.SingleOrDefaultAsync(x => x.Id == id, ct); public Task<bool> SkuExistsAsync(string sku, CancellationToken ct) => db.ProductVariants.AnyAsync(x => x.Sku == sku, ct);
    public Task<bool> BarcodeExistsAsync(string barcode, CancellationToken ct) { Guid? id = db.ChangeTracker.Entries<ProductVariant>().Where(x => x.State == EntityState.Modified && x.Entity.Barcode == barcode).Select(x => (Guid?)x.Entity.Id).SingleOrDefault(); return db.ProductVariants.AnyAsync(x => x.Barcode == barcode && (id == null || x.Id != id), ct); }
    public async Task<IReadOnlyList<ProductVariant>> VariantsAsync(Guid productId, bool activeOnly, CancellationToken ct) => await db.ProductVariants.AsNoTracking().Where(x => x.ProductId == productId && (!activeOnly || x.IsActive)).OrderBy(x => x.Sku).ThenBy(x => x.Id).ToListAsync(ct);
    public async Task<bool> ProductHasDependenciesAsync(Guid id, CancellationToken ct) => await db.ProductVariants.AnyAsync(x => x.ProductId == id, ct) || await db.SupplierProducts.AnyAsync(x => x.ProductId == id, ct) || await db.ProductTechnicalProfiles.AnyAsync(x => x.ProductId == id, ct) || await db.OrderItems.AnyAsync(x => x.ProductId == id, ct) || await db.Tariffs.AnyAsync(x => x.ProductVariantId != null && db.ProductVariants.Any(v => v.Id == x.ProductVariantId && v.ProductId == id), ct);
    public async Task<bool> VariantHasDependenciesAsync(Guid id, CancellationToken ct) => await db.SupplierProducts.AnyAsync(x => x.ProductVariantId == id, ct) || await db.OrderItems.AnyAsync(x => x.ProductVariantId == id, ct) || await db.Tariffs.AnyAsync(x => x.ProductVariantId == id, ct) || await db.ProductTechnicalProfiles.AnyAsync(x => x.ProductVariantId == id, ct);
    public void Remove(Product x) => db.Products.Remove(x); public void Remove(ProductVariant x) => db.ProductVariants.Remove(x); public void Remove(ProductSalesPrice x) => db.ProductSalesPrices.Remove(x);
    public Task<ProductSalesPrice?> GetAsync(Guid id, CancellationToken cancellationToken) => db.ProductSalesPrices.SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
    public async Task<IReadOnlyList<ProductSalesPrice>> ListAsync(Guid productId, bool includeInactive, CancellationToken cancellationToken) => await db.ProductSalesPrices.AsNoTracking().Where(x => x.ProductId == productId && (includeInactive || x.IsActive)).OrderBy(x => x.ProductVariantId).ThenByDescending(x => x.StartDate).ThenBy(x => x.Id).ToListAsync(cancellationToken);
    public Task<bool> OverlapsAsync(Guid productId, Guid? variantId, DateOnly start, DateOnly? end, Guid? excludeId, CancellationToken cancellationToken) => db.ProductSalesPrices.AnyAsync(x => x.ProductId == productId && x.ProductVariantId == variantId && x.Id != excludeId && x.IsActive && x.StartDate <= (end ?? DateOnly.MaxValue) && (x.EndDate == null || x.EndDate >= start), cancellationToken);
    public Task<Supplier?> SupplierAsync(Guid id, CancellationToken ct) => db.Suppliers.SingleOrDefaultAsync(x => x.Id == id, ct); public Task<bool> SupplierCodeExistsAsync(string code, CancellationToken ct) => db.Suppliers.AnyAsync(x => x.SupplierCode == code, ct);
    public Task<PagedResult<Supplier>> SearchSuppliersAsync(CatalogQuery q, CancellationToken ct) => Page(Filter(db.Suppliers.AsNoTracking(), q, x => x.SupplierCode, x => x.DisplayName), q, x => x.SupplierCode, ct);
    public async Task<IReadOnlyList<Supplier>> SupplierOptionsAsync(string? search, int limit, CancellationToken ct) => await Search(db.Suppliers.AsNoTracking().Where(x => x.IsActive), search, x => x.SupplierCode, x => x.DisplayName).OrderBy(x => x.DisplayName).ThenBy(x => x.SupplierCode).Take(limit).ToListAsync(ct);
    public Task<SupplierProduct?> SupplierProductAsync(Guid supplierId, Guid id, CancellationToken ct) => db.SupplierProducts.SingleOrDefaultAsync(x => x.SupplierId == supplierId && x.Id == id, ct);
    public Task<bool> SupplierProductExistsAsync(Guid supplier, Guid product, Guid? variant, CancellationToken ct) => db.SupplierProducts.AnyAsync(x => x.SupplierId == supplier && x.ProductId == product && x.ProductVariantId == variant, ct);
    public async Task<IReadOnlyList<SupplierProduct>> SupplierProductsAsync(Guid supplier, bool activeOnly, CancellationToken ct) => await db.SupplierProducts.AsNoTracking().Where(x => x.SupplierId == supplier && (!activeOnly || x.IsActive)).OrderByDescending(x => x.IsPreferred).ThenBy(x => x.ProductId).ThenBy(x => x.ProductVariantId).ToListAsync(ct);
    public Task<Equipment?> EquipmentAsync(Guid id, CancellationToken ct) => db.Equipment.SingleOrDefaultAsync(x => x.Id == id, ct); public Task<bool> EquipmentCodeExistsAsync(string code, CancellationToken ct) => db.Equipment.AnyAsync(x => x.EquipmentCode == code, ct);
    public Task<PagedResult<Equipment>> SearchEquipmentAsync(CatalogQuery q, CancellationToken ct) { IQueryable<Equipment> values = Filter(db.Equipment.AsNoTracking(), q, x => x.EquipmentCode, x => x.Name); if (!string.IsNullOrWhiteSpace(q.TypeCode)) values = values.Where(x => x.EquipmentTypeCode == q.TypeCode.Trim().ToUpperInvariant()); if (!string.IsNullOrWhiteSpace(q.StatusCode)) values = values.Where(x => x.OperationalStatusCode == q.StatusCode.Trim().ToUpperInvariant()); if (q.BranchId is not null) values = values.Where(x => x.BranchId == q.BranchId); return Page(values, q, x => x.EquipmentCode, ct); }
    public async Task<IReadOnlyList<Equipment>> EquipmentOptionsAsync(string? search, string? type, string? status, Guid? branch, int limit, CancellationToken ct) { IQueryable<Equipment> q = Search(db.Equipment.AsNoTracking().Where(x => x.IsActive), search, x => x.EquipmentCode, x => x.Name); if (!string.IsNullOrWhiteSpace(type)) q = q.Where(x => x.EquipmentTypeCode == type.Trim().ToUpperInvariant()); if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.OperationalStatusCode == status.Trim().ToUpperInvariant()); if (branch is not null) q = q.Where(x => x.BranchId == branch); return await q.OrderBy(x => x.Name).ThenBy(x => x.EquipmentCode).Take(limit).ToListAsync(ct); }
    public Task<bool> BranchExistsAsync(Guid id, CancellationToken ct) => db.Branches.AnyAsync(x => x.Id == id, ct); public Task<bool> UnitExistsAsync(Guid id, CancellationToken ct) => db.OrganizationalUnits.AnyAsync(x => x.Id == id, ct);
    public async Task<IReadOnlyList<SupplierProduct>> ReplacePreferredSupplierProductAsync(SupplierProduct relationship,DateTimeOffset now,CancellationToken ct)
    {
        if(!relationship.IsPreferred||!relationship.IsActive)return [];
        string lockKey="supplier-sourcing:"+relationship.CompanyId.ToString();
        await db.Database.ExecuteSqlInterpolatedAsync($"SELECT pg_advisory_xact_lock(hashtextextended({lockKey},0))",ct);
        var query=db.SupplierProducts.Where(x=>x.Id!=relationship.Id&&x.ProductId==relationship.ProductId&&
            x.ProductVariantId==relationship.ProductVariantId&&x.IsPreferred&&x.IsActive);
        var previous=await query.AsNoTracking().ToListAsync(ct);
        await query.ExecuteUpdateAsync(update=>update.SetProperty(x=>x.IsPreferred,false).SetProperty(x=>x.Version,x=>x.Version+1).SetProperty(x=>x.UpdatedAtUtc,now),ct);
        return previous;
    }
    private static IQueryable<T> Filter<T>(IQueryable<T> source, CatalogQuery q, System.Linq.Expressions.Expression<Func<T, string>> code, System.Linq.Expressions.Expression<Func<T, string>> name) where T : CatalogEntity { IQueryable<T> value = source.Where(x => !q.ActiveOnly || x.IsActive); return Search(value, q.Search, code, name); }
    private static IQueryable<T> Search<T>(IQueryable<T> source, string? search, System.Linq.Expressions.Expression<Func<T, string>> code, System.Linq.Expressions.Expression<Func<T, string>> name) { string value = search?.Trim() ?? ""; if (value.Length == 0) return source; string pattern = $"%{value.Replace("%", "\\%").Replace("_", "\\_")}%"; return source.Where(BuildSearch(code, name, pattern)); }
    private static System.Linq.Expressions.Expression<Func<T, bool>> BuildSearch<T>(System.Linq.Expressions.Expression<Func<T, string>> code, System.Linq.Expressions.Expression<Func<T, string>> name, string pattern) { var p = code.Parameters[0]; var functions = System.Linq.Expressions.Expression.Property(null, typeof(EF), nameof(EF.Functions)); var method = typeof(NpgsqlDbFunctionsExtensions).GetMethods().Single(x => x.Name == nameof(NpgsqlDbFunctionsExtensions.ILike) && x.GetParameters().Length == 4); var c = System.Linq.Expressions.Expression.Call(method, functions, code.Body, System.Linq.Expressions.Expression.Constant(pattern), System.Linq.Expressions.Expression.Constant("\\")); var n = System.Linq.Expressions.Expression.Call(method, functions, new ReplaceParameter(name.Parameters[0], p).Visit(name.Body)!, System.Linq.Expressions.Expression.Constant(pattern), System.Linq.Expressions.Expression.Constant("\\")); return System.Linq.Expressions.Expression.Lambda<Func<T, bool>>(System.Linq.Expressions.Expression.OrElse(c, n), p); }
    private static async Task<PagedResult<T>> Page<T>(IQueryable<T> query, CatalogQuery request, System.Linq.Expressions.Expression<Func<T, string>> order, CancellationToken ct) where T : CatalogEntity { PagedRequest page = new(request.PageNumber, request.PageSize); long total = await query.LongCountAsync(ct); List<T> rows = await query.OrderBy(order).ThenBy(x => x.Id).Skip((page.PageNumber - 1) * page.PageSize).Take(page.PageSize).ToListAsync(ct); return new(rows, page.PageNumber, page.PageSize, total); }
    private sealed class ReplaceParameter(System.Linq.Expressions.ParameterExpression oldValue, System.Linq.Expressions.ParameterExpression newValue) : System.Linq.Expressions.ExpressionVisitor { protected override System.Linq.Expressions.Expression VisitParameter(System.Linq.Expressions.ParameterExpression node) => node == oldValue ? newValue : base.VisitParameter(node); }
}
